    for (let k = 0; k < col.count; k++)
      if (col.d[k * 4 + 3] < 0.01 && Math.abs(col.d[k * 4] - 0.78) < 0.01 && Math.abs(col.d[k * 4 + 1] - 0.80) < 0.01 && Math.abs(col.d[k * 4 + 2] - 0.82) < 0.01) n++;
    assert.ok(n > 0, `${f}: không thấy đỉnh màu inox`);
  }
});
